inlineStyleBlocks:
body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: #0f172a;
            color: #f1f5f9;
            min-height: 100vh;
            margin: 0;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            padding: 24px;
        }
        .code { font-size: 5em; margin: 0; opacity: 0.9; }
        h1 { font-size: 1.4em; margin: 12px 0 8px; }
        p { color: #94a3b8; margin: 0 0 28px; }
        a {
            color: #fff;
            background: #6366f1;
            text-decoration: none;
            padding: 12px 28px;
            border-radius: 8px;
            font-weight: 600;
        }
        a:hover { background: #4f46e5; }
